        parts = base.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre1, pre2):
        # pre1 and pre2 are lists of prerelease identifiers
        # A version without prerelease sorts after one with prerelease
        if not pre1 and not pre2:
            return 0
        if not pre1:
            return 1  # no prerelease sorts after prerelease
        if not pre2:
            return -1  # prerelease sorts before no prerelease

        # Compare each identifier
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric, compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 != num2:
                    return -1 if num1 < num2 else 1
            elif is_num1:
                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare lexically
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        # All shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

