    indexed_versions = []
    for i, v in enumerate(versions):
        parsed = parse_version(v)
        indexed_versions.append((parsed, i, v))

    # Sort using custom comparison
    def sort_key(item):
        parsed, index, _ = item
        major, minor, patch, prerelease = parsed

        # Create a sortable key
        # First sort by major, minor, patch numerically
        # Then by prerelease (with special handling)
        # Then by original index for stable sort

        # For prerelease comparison in key, we need to convert to a comparable form
        prerelease_key = []
        if prerelease:
            for identifier in prerelease:
                if identifier.isdigit():
                    # Numeric identifiers: use (0, numeric_value) to sort before non-numeric
                    prerelease_key.append((0, int(identifier)))
                else:
                    # Non-numeric identifiers: use (1, string_value)
                    prerelease_key.append((1, identifier))
            prerelease_key = (0, tuple(prerelease_key))  # versions with prerelease come first
        else:
            prerelease_key = (1,)  # versions without prerelease come second

        return (major, minor, patch, prerelease_key, index)

    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for _, _, v in sorted_versions]

